CREATE TABLE "trip_recommendation_contexts" ("user_id" text NOT NULL, "conversation_id" text NOT NULL, "revision" integer NOT NULL, "fingerprint" text NOT NULL, "updated_at" timestamp DEFAULT now() NOT NULL, CONSTRAINT "trip_recommendation_contexts_user_id_conversation_id_pk" PRIMARY KEY("user_id","conversation_id"), CONSTRAINT "trip_recommendation_contexts_owner_fk" FOREIGN KEY ("conversation_id","user_id") REFERENCES "conversations"("id","user_id") ON DELETE cascade, CONSTRAINT "trip_recommendation_contexts_revision_check" CHECK ("revision" >= 1), CONSTRAINT "trip_recommendation_contexts_fingerprint_check" CHECK ("fingerprint" ~ '^[a-f0-9]{64}$'));
