CREATE TABLE "trip_recommendation_decisions" ("id" text PRIMARY KEY NOT NULL, "user_id" text NOT NULL, "conversation_id" text NOT NULL, "kind" text NOT NULL, "context_revision" integer NOT NULL, "context_fingerprint" text NOT NULL, "candidate_trip_project_id" text, "status" text DEFAULT 'open' NOT NULL, "created_at" timestamp DEFAULT now() NOT NULL, "consumed_at" timestamp, CONSTRAINT "trip_recommendation_decisions_owner_fk" FOREIGN KEY ("conversation_id","user_id") REFERENCES "conversations"("id","user_id") ON DELETE cascade, CONSTRAINT "trip_recommendation_decisions_candidate_owner_fk" FOREIGN KEY ("candidate_trip_project_id","user_id") REFERENCES "trip_projects"("id","user_id") ON DELETE cascade, CONSTRAINT "trip_recommendation_decisions_kind_check" CHECK ("kind" in ('creation','context')), CONSTRAINT "trip_recommendation_decisions_revision_check" CHECK ("context_revision" >= 1), CONSTRAINT "trip_recommendation_decisions_fingerprint_check" CHECK ("context_fingerprint" ~ '^[a-f0-9]{64}$'), CONSTRAINT "trip_recommendation_decisions_status_check" CHECK ("status" in ('open','consumed','declined','private')));
