CREATE TABLE "trip_recommendation_declines" ("user_id" text NOT NULL, "conversation_id" text NOT NULL, "context_revision" integer NOT NULL, "fingerprint" text NOT NULL, "created_at" timestamp DEFAULT now() NOT NULL, CONSTRAINT "trip_recommendation_declines_user_id_conversation_id_context_revision_pk" PRIMARY KEY("user_id","conversation_id","context_revision"), CONSTRAINT "trip_recommendation_declines_owner_fk" FOREIGN KEY ("conversation_id","user_id") REFERENCES "conversations"("id","user_id") ON DELETE cascade, CONSTRAINT "trip_recommendation_declines_revision_check" CHECK ("context_revision" >= 1), CONSTRAINT "trip_recommendation_declines_fingerprint_check" CHECK ("fingerprint" ~ '^[a-f0-9]{64}$'));
