CREATE TABLE "trip_recommendation_acceptances" ("user_id" text NOT NULL, "idempotency_key" text NOT NULL, "request_digest" text NOT NULL, "decision_id" text, "terminal_result" jsonb NOT NULL, "created_at" timestamp DEFAULT now() NOT NULL, CONSTRAINT "trip_recommendation_acceptances_user_id_idempotency_key_pk" PRIMARY KEY("user_id","idempotency_key"), CONSTRAINT "trip_recommendation_acceptances_key_check" CHECK ("idempotency_key" ~ '^[A-Za-z0-9_-]{16,128}$'), CONSTRAINT "trip_recommendation_acceptances_digest_check" CHECK ("request_digest" ~ '^[a-f0-9]{64}$'));
